import { useEffect, useRef } from "react";

export const useOutsideClick = (callback: () => void) => {
  const handlersRef = useRef<Map<Element, () => void>>(new Map());

  useEffect(() => {
    const handleClick = (event: MouseEvent) => {
      const handlers = handlersRef.current;
      handlers.forEach((callback, element) => {
        if (element && !element.contains(event.target as Node)) {
          callback();
        }
      })
    };

    document.addEventListener('mousedown', handleClick);

    return () => {
      document.removeEventListener('mousedown', handleClick);
    };
  }, []);

  return (element: Element | null) => {
    if (!element) return;

    handlersRef.current.set(element, callback);

    return () => {
      handlersRef.current.delete(element);
    }
  };
};

import { KeyHandlers, KeyPressOptions } from '../types';

export const keyPress = (handlers: KeyHandlers, options: KeyPressOptions = {}) => {
  const { preventDefault = false, caseSensitive = false } = options;

  return (event: KeyboardEvent) => {
    const { key } = event;

    // 기본 키 매핑
    const defaultKeyMap: Record<string, keyof KeyHandlers> = {
      'Enter': 'onEnter',
      'Escape': 'onEscape',
      ' ': 'onSpace',
      'Tab': 'onTab',
      'ArrowUp': 'onArrowUp',
      'ArrowDown': 'onArrowDown',
      'ArrowLeft': 'onArrowLeft',
      'ArrowRight': 'onArrowRight',
    };

    let handlerName: keyof KeyHandlers | undefined;

    if (defaultKeyMap[key]) {
      handlerName = defaultKeyMap[key];
    } else {
      // 커스텀 키 처리
      const normalizedKey = caseSensitive ? key : key.toLowerCase();
      handlerName = normalizedKey as keyof KeyHandlers;
    }

    if (handlerName && handlers[handlerName]) {
      const shouldPreventDefault = 
        preventDefault === true || 
        (Array.isArray(preventDefault) && preventDefault.includes(key));

      if (shouldPreventDefault) {
        event.preventDefault();
      }

      handlers[handlerName]!(event);
    }
  };
};

import React, { useRef, useEffect } from 'react';
import { useOutsideClick } from '../hooks/useOutsideClick';
import { keyPress } from '../utils/keyPress';
import { ModalProps } from '../types';

function Modal({ 
  isOpen, 
  message, 
  onConfirm, 
  onCancel,
  enableOutsideClick = true,
  enableKeyboardShortcuts = true,
  showCancelButton = true 
}: ModalProps) {
  const modalRef = useRef<HTMLDivElement>(null);

  // 외부 클릭으로 모달 닫기
  const registerOutsideClick = useOutsideClick(() => {
    if (enableOutsideClick && onCancel) {
      onCancel();
    }
  });

  // 키보드 이벤트 처리
  const handleKeyPress = keyPress({
    onEscape: () => {
      if (enableKeyboardShortcuts && onCancel) {
        onCancel();
      }
    },
    onEnter: () => {
      if (enableKeyboardShortcuts && onConfirm) {
        onConfirm();
      }
    }
  }, { preventDefault: ['Escape', 'Enter'] });

  // 외부 클릭 등록
  useEffect(() => {
    if (modalRef.current && isOpen) {
      return registerOutsideClick(modalRef.current);
    }
  }, [registerOutsideClick, isOpen]);

  // 키보드 이벤트 등록
  useEffect(() => {
    if (isOpen && enableKeyboardShortcuts) {
      document.addEventListener('keydown', handleKeyPress);
      return () => {
        document.removeEventListener('keydown', handleKeyPress);
      };
    }
  }, [isOpen, handleKeyPress, enableKeyboardShortcuts]);

  // 모달이 열릴 때 포커스 설정
  useEffect(() => {
    if (isOpen && modalRef.current) {
      modalRef.current.focus();
    }
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div 
        className="modal-content enhanced-modal" 
        ref={modalRef}
        tabIndex={-1}
      >
        <div className="modal-header">
          <h3>알림</h3>
          {enableKeyboardShortcuts && (
            <div className="modal-shortcuts">
              <small>ESC: 취소 | Enter: 확인</small>
            </div>
          )}
        </div>

        <div className="modal-body">
          <p>{message}</p>
        </div>

        <div className="modal-buttons">
          <button 
            onClick={onConfirm ? onConfirm : undefined} 
            className="confirm-btn"
            autoFocus
          >
            확인
          </button>
          {showCancelButton && (
            <button onClick={onCancel ? onCancel : undefined} className="cancel-btn">
              취소
            </button>
          )}
        </div>

        {enableOutsideClick && (
          <div className="modal-hint">
            <small>모달 외부를 클릭하거나 ESC키를 눌러 닫을 수 있습니다</small>
          </div>
        )}
      </div>
    </div>
  );
}

export default Modal;

import { createContext, useContext, useState, useCallback } from "react";
import Modal from "../components/Modal";
import { ModalOptions, ModalContextType, ModalProviderProps } from "../types";

interface ModalState {
  isOpen: boolean;
  message: string;
  onConfirm: (() => void) | null;
  onCancel: (() => void) | null;
  options: ModalOptions;
}

const ModalContext = createContext<ModalContextType | undefined>(undefined);

export const useModal = (): ModalContextType => {
  const context = useContext(ModalContext);
  if (!context) {
    throw new Error('useModal must be used within a ModalProvider');
  }
  return context;
};

export const ModalProvider = ({ children }: ModalProviderProps) => {
  const [modalState, setModalState] = useState<ModalState>({
    isOpen: false,
    message: '',
    onConfirm: null,
    onCancel: null,
    options: {}
  });

  const showModal = useCallback(async (message: string, options: ModalOptions = {}): Promise<boolean> => {
    const {
      enableOutsideClick = true,
      enableKeyboardShortcuts = true,
      showCancelButton = true,
      ...otherOptions
    } = options;

    return new Promise<boolean>((resolve) => {
      setModalState({
        isOpen: true,
        message,
        onConfirm: () => {
          setModalState({
            isOpen: false,
            message: '',
            onConfirm: null,
            onCancel: null,
            options: {}
          });
          resolve(true);
        },
        onCancel: () => {
          setModalState({
            isOpen: false,
            message: '',
            onConfirm: null,
            onCancel: null,
            options: {}
          });
          resolve(false);
        },
        options: {
          enableOutsideClick,
          enableKeyboardShortcuts,
          showCancelButton,
          ...otherOptions
        }
      });
    });
  }, []);

  return (
    <ModalContext.Provider value={{ 
      confirm: showModal,
      alert: (message: string) => showModal(message, { showCancelButton: false })
    }}>
      {children}
      <Modal {...modalState} {...modalState.options} />
    </ModalContext.Provider>
  );
};

import { useState, useCallback } from 'react';

const useToggle = (initialValue = false) => {
  const [value, setValue] = useState(initialValue);

  const toggle = useCallback(() => setValue(!value), [value]);
  const setTrue = useCallback(() => setValue(true), []);
  const setFalse = useCallback(() => setValue(false), []);

  return [value, toggle, setTrue, setFalse];
};

export default useToggle;
